// Handle both direct body and nested body.body (plugin compatibility)
const rawBody = $input.first().json.body || $input.first().json;
const body = rawBody.body || rawBody;

const required = ['prompt', 'lesson_id', 'guild_id'];
const missing = required.filter(field => !body[field]);

// Also need topic OR content
if (!body.topic && !body.content) {
  missing.push('topic or content');
}

if (missing.length > 0) {
  return {
    json: {
      valid: false,
      error: {
        code: 400,
        message: `Missing required parameters: ${missing.join(', ')}`,
        status: 'BAD_REQUEST',
        received_fields: Object.keys(body)
      }
    }
  };
}

// Pass normalized body for downstream nodes
return {
  json: {
    valid: true,
    body: body
  }
};

const body = $('Validate Input').first().json.body;
const llmResponse = $input.first().json;

try {
  const content = llmResponse.content?.[0]?.text || '';

  // Find JSON in the response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const quizData = JSON.parse(jsonStr);

  // Build quiz object for API
  const quiz = {
    lesson_id: body.lesson_id,
    guild_id: body.guild_id,
    title: quizData.title,
    description: quizData.description,
    instructions: quizData.instructions,
    type: body.adaptive ? 'adaptive' : 'standard',
    time_limit_seconds: body.time_limit_seconds || 600,
    passing_score: body.passing_score || 70,
    questions: quizData.questions.map((q, i) => ({
      text: q.text,
      type: q.type,
      options: q.options,
      correct_answer: q.correct_answer,
      explanation: q.explanation,
      difficulty: q.difficulty || 2,
      order_index: q.order_index || i,
      points: q.points || (q.difficulty === 1 ? 10 : q.difficulty === 3 ? 20 : 15)
    }))
  };

  return {
    json: {
      success: true,
      quiz: quiz,
      guild_id: body.guild_id
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse quiz: ' + e.message,
        raw_response: llmResponse.content?.[0]?.text?.substring(0, 500)
      }
    }
  };
}

const apiResponse = $input.first().json;
const body = $('Validate Input').first().json.body;

return {
  json: {
    success: true,
    data: {
      quiz_id: apiResponse.id,
      title: apiResponse.title,
      questions_count: apiResponse.questions?.length || 0,
      total_points: apiResponse.total_points,
      passing_score: apiResponse.passing_score
    },
    meta: {
      workflow: 'learning-generate-quiz',
      provider: 'anthropic',
      model: body.model || 'claude-3-haiku-20240307',
      timestamp: new Date().toISOString()
    }
  }
};
